//! Writing converted declarations as an `entities.toml`.

use crate::load::RawSchema;

/// The comment a generated schema opens with: the JSON Schema an editor
/// validates it against, and a warning that edits are lost.
const HEADER: &str = "\
#:schema https://raw.githubusercontent.com/nachstedt/rinx/main/schemas/entities.schema.json
#
# GENERATED by `rinx needs_schema` from a sphinx-needs configuration.
# Edits are lost when it is generated again.

";

/// `schema` as the text of an `entities.toml`.
///
/// The `[import_keys]` table comes before the first `[[entity_type]]`, as
/// [`RawSchema`] declares it first: written after an array of tables it would
/// still be top-level, but it would read as if it were nested.
///
/// # Panics
///
/// Never: every declaration is a string, a boolean, a list or a table, all
/// of which TOML writes.
#[must_use]
pub fn render_schema_toml(schema: &RawSchema) -> String {
    let body = toml::to_string(schema).expect("entity schema declarations are always serializable");
    format!("{HEADER}{body}")
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::load::{NoReservedNames, load_raw_schema, load_schema};
    use crate::needs_conf::{NeedsConfig, convert_needs};

    fn config(toml_text: &str) -> NeedsConfig {
        NeedsConfig::from_toml(toml_text, crate::needs_conf::DEFAULT_TOML_ROOT)
            .expect("a valid configuration")
            .0
    }

    #[test]
    fn test_the_generated_file_announces_that_it_is_generated() {
        // Given any conversion
        let (schema, _) = convert_needs(&config("[[needs.types]]\ndirective = \"req\"\n"), None);

        // When
        let text = render_schema_toml(&schema);

        // Then a reader who opens it is told not to edit it
        assert!(text.contains("GENERATED by `rinx needs_schema`"));
    }

    #[test]
    fn test_the_text_loads_as_the_schema_it_was_rendered_from() {
        // Given a conversion using every kind of declaration
        let (schema, _) = convert_needs(
            &config(
                r#"
[needs]
id_required = true
import_keys = { upstream = "/u.json" }

[[needs.types]]
directive = "req"
title = "Requirement"
prefix = "R_"

[[needs.types]]
directive = "spec"

[needs.fields.effort]
schema = { type = "integer", enum = [1, 2] }

[needs.links.reqs]
outgoing = "specifies"
incoming = "specified by"
"#,
            ),
            None,
        );

        // When
        let text = render_schema_toml(&schema);

        // Then
        let from_text = load_schema(&text, &NoReservedNames).expect("the text loads");
        let direct = load_raw_schema(schema, &NoReservedNames).expect("the declarations load");
        assert_eq!(from_text, direct);
        assert_eq!(from_text.import_keys(), direct.import_keys());
    }

    #[test]
    fn test_the_import_keys_table_comes_before_the_first_entity_type() {
        // Given a project declaring both an import key and a type
        let (schema, _) = convert_needs(
            &config(
                "[needs]\nimport_keys = { upstream = \"/u.json\" }\n[[needs.types]]\ndirective = \"req\"\n",
            ),
            None,
        );

        // When
        let text = render_schema_toml(&schema);

        // Then
        let keys = text.find("[import_keys]").expect("the table is written");
        let first_type = text.find("[[entity_type]]").expect("the type is written");
        assert!(keys < first_type);
    }

    #[test]
    fn test_a_project_without_import_keys_writes_no_table() {
        // Given
        let (schema, _) = convert_needs(&config("[[needs.types]]\ndirective = \"req\"\n"), None);

        // When
        let text = render_schema_toml(&schema);

        // Then nothing is written, rather than an empty table
        assert!(!text.contains("import_keys"));
    }

    #[test]
    fn test_a_pattern_keeps_its_backslashes() {
        // Given a regex holding a backslash
        let mut schema = convert_needs(&config("[[needs.types]]\ndirective = \"req\"\n"), None).0;
        schema.entity_type[0].id = Some(crate::load::RawId {
            pattern: Some(r"^R_\d+$".to_string()),
            ..Default::default()
        });

        // When
        let text = render_schema_toml(&schema);

        // Then the TOML string decodes back to the regex as written
        let loaded = load_schema(&text, &NoReservedNames).expect("the text loads");
        let pattern = loaded
            .entity_type("req")
            .and_then(|t| t.id.pattern.as_ref());
        assert_eq!(pattern.map(crate::ValuePattern::as_str), Some(r"^R_\d+$"));
    }
}
